-- Harbour & Home: made-up data for Avro Academy's SQL for Data Analysts course
BEGIN TRANSACTION;
CREATE TABLE channels (
  channel_id   INTEGER PRIMARY KEY,
  channel_name TEXT NOT NULL
);
CREATE TABLE customers (
  customer_id INTEGER PRIMARY KEY,
  first_name  TEXT NOT NULL,
  last_name   TEXT NOT NULL,
  email       TEXT NOT NULL,
  state       TEXT,
  city        TEXT,
  signup_date TEXT NOT NULL,          -- YYYY-MM-DD
  channel_id  INTEGER REFERENCES channels(channel_id)
);
CREATE TABLE order_items (
  order_id   INTEGER NOT NULL REFERENCES orders(order_id),
  product_id INTEGER NOT NULL REFERENCES products(product_id),
  quantity   INTEGER NOT NULL,
  unit_price REAL NOT NULL,           -- the price paid, which can differ from list_price
  PRIMARY KEY (order_id, product_id)
);
CREATE TABLE orders (
  order_id      INTEGER PRIMARY KEY,
  customer_id   INTEGER NOT NULL REFERENCES customers(customer_id),
  order_date    TEXT NOT NULL,        -- YYYY-MM-DD
  status        TEXT NOT NULL,        -- delivered or cancelled
  shipping_fee  REAL,
  discount_code TEXT,
  discount      REAL NOT NULL DEFAULT 0
);
CREATE TABLE products (
  product_id    INTEGER PRIMARY KEY,
  product_name  TEXT NOT NULL,
  category      TEXT NOT NULL,
  list_price    REAL NOT NULL,        -- current price, AUD incl. GST
  unit_cost     REAL NOT NULL,        -- what the store pays the supplier
  launched_date TEXT NOT NULL
);
CREATE TABLE returns (
  return_id     INTEGER PRIMARY KEY,
  order_id      INTEGER NOT NULL REFERENCES orders(order_id),
  product_id    INTEGER NOT NULL REFERENCES products(product_id),
  return_date   TEXT NOT NULL,
  reason        TEXT NOT NULL,
  refund_amount REAL NOT NULL
);
COMMIT;
